from collections import defaultdict

def paint_edges(m, edges, ants):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append((u, v))
        graph[v].append((v, u))

    def is_possible(n_edges, edges, ants):
        adj = [[] for _ in range(n_edges)]
        for _, a, b, c, d in ants:
            adj[a - 1].append((a - 1, b - 1))
            adj[b - 1].append((b - 1, c - 1))
            adj[c - 1].append((c - 1, d - 1))

        visited = [False] * n_edges
        for i in range(n_edges):
            if visited[i]:
                continue
            colors = [None] * n_edges
            colors[i] = 0
            queue = [(i, 0)]
            while queue:
                u, c = queue.pop(0)
                if c and colors[u] is not None and colors[u] != c:
                    return False
                if colors[u] is None:
                    colors[u] = c
                visited[i] = True
                for v in graph[u]:
                    if colors[v[1]] is None:
                        queue.append((v[1], c if c == colors[u] else (c + 1) % 3))

        if colors[n_edges - 1] is None:
            return False

        for i in range(1, len(ants)):
            a, b, c, d = ants[i]
            u, v = ants[i - 1][0]
            if (colors[n_edges - 1] != 1 and u == a or v == d) or (colors[n_edges - 1] != 2 and u == b or v == c):
                return False
        return True

    for i in range(1, m):
        for j in range(1, m):
            if i > j:
                break
            cnt = 0
            for k in range(i, j + 1):
                u, v = ants[k][0], ants[k][1]
                for u1, v1 in ants[k - i]:
                    if u == u1 or v == v1:
                        cnt += 1
            if 2 * cnt < j - i + 1:
                return 'NO'

    if is_possible(m, edges, ants):
        return 'YES\n'
    else:
        return 'NO\n'

