                        min_cost[p] = visit_index[i] = t - s
                        add_edge(i, t + T)
        for s in range(0, 3 * c // 4 - T):
            if manhattan_distances[p] + s <= T and visit_index[arrival_time[p - s]] < min_cost[p] and t := arrival_time[p - s]:
                min_cost[p] = min(min_cost[p], arr_time[p - s] - visit_index[t])
                add_edge(hi(arrival_time, t - s - min_cost[p] + T), t + T)

    # Initialize BFS queue
    for i in range(n):
        q = deque([i])
        visited[arrival_time[i]] = 0
        while len(q):
            i = q.popleft()
            visited[arrival_time[i]] = max(visited[i], min_cost[p])
            for j in [i - q.queue_engines]:
                cost = d + visited[j] + T * c
                if min_cost[p] > cost:
                    min_cost[p] = cost
