def dfs(start, graph, visited):
    forest = []
    stack = [start]
    while stack:
        current = stack.pop()
        if current not in visited:
            visited.add(current)
            forest.append(current)
            graph[start].append(current)
            for next in dfs_adjacent(next):
                stack.append(next)
    return forest

def dfs_adjacent(node):
