from collections import deque

def is_possible(n, edges, ants):
    color_pairs = []
    visited = [False] * n
    for i, (a, b) in enumerate(zip(ants[::2], ants[1::2])):
        visited[a-1] = visited[b-1] = True
        pairs = []
        for u, v in edges:
            if visited[u-1]:
                pairs.append((u, v))
            if visited[v-1]:
                pairs.append((v, u))
        color_pairs.append(pairs)

    queue = deque(enumerate(color_pairs, 1))
    seen = set()
    scores = [0] * n

    while queue:
        pair, _ = queue.popleft()
        for other in queue:
            other_pair, other_index = other
            if not seen[other_index] and pair != other_pair:
                if all(a == pair or b == other_pair for a, b in zip(color_pairs[other[1]], other_pair)):
                    continue
                scores[pair[0] - 1] += 6 / len(edges)
                scores[other_pair[0] - 1] += 6 / len(edges)

    max_score = max(scores)
    min_score = min(scores)

    odds = {i for i, score in enumerate(scores) if score > min_score}
    evens = {i for i, score in enumerate(scores) if score < max_score}

    result = []
    seen_ans = set()
    for i, (a, b) in enumerate(zip(ants[::2], ants[1::2])):
        seen_ans.add(a)
        if (a, b) in seen_ans:
            seen_ans.add(b)
        if len(seen_ans) == len(ants):
            break
        if (i in odds or i in evens) == len(ants) % 2:
            if len(odds) < len(evens):
                result.append(1)
            else:
                result.append(2)

    return 'YES\n'.join(map(str, result))

# Reading inputs
