            if sum_temp > 0 and sum_temp in positions:
                return (i + 1) * (positions - {sum_val + sum_temp}) * (positions - {sum_temp})
        positions.add(sum_temp)
    positions.discard(total)
    return ''.join(list(map(str, list(positions))).split())

def solve(N, A):
    return sum(count_equal_sum_subarrays(A[:i] + A[i+1:]) for i in range(1, N))

