from math import gcd
from typing import List

def find_gcd(list_of_values: List[int]) -> int:
    """Calculate the greatest common divisor of the absolute differences between every pair of values."""
    differences = [abs(a - b) for a, b in zip(list_of_values, list_of_values[1:])]
    return gcd(*differences)

def is_possible_to_solve(config: List[int], graph: List[List[int]]) -> bool:
    """Check if it's possible to achieve the given config with the specified operations."""
    leaf_values = set(config)
    if not any((leaf_values - {0}).issubset(leaf_set) for leaf_set in graph):
        return False
    g = graph[-1][0][0]
    k = min(config)
    return float('inf') > find_gcd(config[g:] + config[:g] + [-k])

def generate_operations(number_of_operations: int, graph: List[List[int]]) -> List[List[int]]:
    """Generate possible sequences of operations based on the given graph and config."""
    operations = []
    for i, v in enumerate(config):
        if v > 0:
            operations.append([i, j, v] for j in graph[i][0])
    return operations

def solve(config: List[int], graph: List[List[int]]) -> None:
    """Print 'NO' if no solution exist, otherwise print YES with number of operations required."""
    if not is_possible_to_solve(config, graph):
        print("NO")
    else:
        print("YES")
        print(number_of_operations)
        for op in generate_operations(number_of_operations, graph):
            print(' '.join(map(str, op)))

