from collections import defaultdict

def find_path(x, y, direction, time):
    if direction == 'U':
        if x > 0:
            x -= 1
    elif direction == 'D':
        if x < b:
            x += 1
    elif direction == 'L':
        if y > 0:
            y -= 1
    elif direction == 'R':
        if y < b:
            y += 1
    return (x, y)

def find_entrance_coordinates(time, b):
    directions = defaultdict(lambda: b)
    for x in range(b + 1):
        for y in range(b + 1):
            i = int(time // (b + 1) * (2 * b))
            if i % 2 == 1:
                directions[(x, y)] = i
                i += int((0.5 + (time % (b + 1)) * 0.5) / (b + 1)) - 0.5
                directions[(x, y + int(1 / ((1 / (time % (b + 1)) * (b + 1)) + 1))) if y + int(1 / ((1 / (time % (b + 1)) * (b + 1)) + 1)) <= b else (int(b + 1), int(b + 1))]
            else:
                directions[(x, y)] = i
                i += int((0.5 + (time % (b + 1)) * 0.5) / (b + 1)) - 0.5
                directions[(x + int(1 / ((1 / (time % (b + 1)) * (b + 1)) + 1)), y if y + int(1 / ((1 / (time % (b + 1)) * (b + 1)) + 1)) <= b else int(b + 1))]
    return (directions[0], directions[1])

def compute_plan_answer(time, start_x, start_y, start_direction, directions, tiles):
