from math import comb

def find_next_permutation(length):
    incremented = [i+1 for i in range(1, length)] + [0]
    n = length - 1
    for i in range(len(incremented) - 2, -1, -1):
        incremented[n-i] = incremented[n-i+1] + 1
    return incremented[1:]

def count_i_beautiful_permutations(n, m, i):
    count = 0
    permutations = find_next_permutation((i * n + 1) // 2)
    for j in range(1, i * n + 1):
        pair = (permutations[j % (i * n + 1)], permutations[(j+i*n+1)% (i*n+1)])
        if not pair_equal(pair[0], pair[1], m):
            count += 1
    return count

def pair_equal(x, y, mod):
    return pow(x[0] + x[1], 2, mod) == pow(y[0] + y[1], 2, mod)

def solution(K, M):
    results = []
    for _ in range(K):
        results.append(count_i_beautiful_permutations(2, M, 1))
    return results

