from math import factorial
from fractions import Fraction
from collections import defaultdict

def get_2binom(n, k):
    return factorial(n) / (factorial(k) * factorial(n - k))

def beauty_maps(k):
    mod = 1000000007
    num = 1
    for _ in range(k):
        num = (num * 2) % mod
    return num

def binom2(k):
    return get_2binom(2 * k, k)

def main():
    k, m = map(int, input().split())
    # Apply the beauty maps for each i
    answers = defaultdict(int)
    for i in range(1, k + 1):
        answers[i] = binom2(i) % m
    # Reduce the number of permutations based on the mod factor
    rev_perms = defaultdict(int)
    for n, f in answers.items():
        x = n**-1 % m
        while x > 1:
            if x in rev_perms:
                rev_perms[x] *= f
                rev_perms[x] %= m
            else:
                rev_perms[x] = f
            x -= 1
    # Transform the dictionary back to an array of values
    num_answers = []
    for n, f in answers.items():
        n = n * (k - 1) / (n - 1)
        num_answers.extend([f * d for d in rev_perms.get(n, [1])])
    # Sort and output the results, then reset maps
    res = sorted(num_answers)
    for n in reversed(res):
        answers[n] -= 1
        if answers[n] == 0:
            answers.pop(n)
    nvec = []
    for k in answers.keys():
        n = k**(-1) % m
        while n > 1:
            nvec.extend([answers.pop(n)])
            n -= 1
    for v in nvec:
        print(v, end=' ')
    print()

if __name__ == "__main__":
    main()
