import sys
from heapq import heappop, heappush

def dijkstra(graph, start, portals, portals_moves):
    # Initialize distances and set start distance
    distances = {city: float('inf') for city in graph}
    distances[start] = 0
    visited = {city: False for city in graph}
    heap = [(0, start)]

    # Priority queue for closest cities
    heap_priority_queue = []

    while heap:
        # Take a vertex with the nearest distance
        current_distance, current_city = heappop(heap)
        if visited[current_city]:
            continue
        visited[current_city] = True
        for neighbor, distance in graph[current_city]:
            total_distance = current_distance + distance
            if total_distance < distances[neighbor]:
                distances[neighbor] = total_distance
                heappush(heap, (total_distance, neighbor))
            elif total_distance == distances[neighbor]:
                heappush(heap_priority_queue, (distance - distances[neighbor] + distance, neighbor))
                heappop(heap)
                distances[neighbor] = total_distance
            elif not portals_moves[neighbor]:
                edges = [(distance, not door) for distance, door in portals[current_city]]
                wins = max(edges)
                if current_city in portals_moves:
                    wins = max(wins, (distance, wins[1]))
                total_wins = min(edges) + wins[0] - wins[1]
                if total_wins > 1:
                    heappush(heap, (wins[0], neighbor))
                    heappop(heap_priority_queue)

    return distances

def solve(n, m, roads, k, portals):
