import sys
from collections import defaultdict
from heapq import heappush, heappop

def read():
    return sys.stdin.readline().strip()

def get_ancestors(num_nodes, tree, k):
    parent = [i for i in range(num_nodes)]
    q = [(i, i) for i in range(num_nodes)]
    for i in tree[k]:
        while q and q[-1][1] < i:
            q.pop()
        if q and tree[q[-1][0]][q[-1][1]] == i:
            j = q[-1][1]
            tree[i][j] = tree[i][j] if tree[i][j] else i
            q.pop()
        q.append((i, i))
    return parent

def dfs(root, parent, tree, used):
    order = [root]
    path = []
    while True:
        while tree[root] and tree[root][parent] == root:
            root = tree[root][parent]
            path.append(root)
        path.append(root)
        if not path:
            break
        root = path[-1]
    for i in tree[root]:
        if i not in path:
            if i not in order or i == order[-2]:
                path.append(i)
                used.insert(0, tree[i])
                dfs(i, i, tree, used)
    order += path[::-1]
    return order, used

def post_order(root, parent, tree, order):
    order.append(root)
    while True:
        while tree[root] and tree[root][parent] == root:
            root = tree[root][parent]
        if root in order or not tree[root]:
            break
        order.append(root)
        root = tree[root][parent]
    return order

def solve(num_nodes, tree):
    max_val, max_val_list = (-1, -1), []

    ancestors = get_ancestors(num_nodes, tree, 1)
    roots = [i for i in range(num_nodes) if i not in ancestors[1:]]
    order = []
    for root in roots:
        used = []
        subtree_order, subtree_used = dfs(root, root, tree, used)
        unused = len(set(subtree_order) - set(subtree_used))
        max_order, max_used = (-1, -1)
        for i in subtree_used:
            if len(subtree_used) - subtree_order.count(i) > max_order:
                max_order, max_used = subtree_order.count(i), i
        order.append((subtree_order.count(i), i))
        if len(subtree_order) > max_val[0] or (len(subtree_order) == max_val[0] and len(subtree_order) > max_val[1] or subtree_order.count(max_used) < max_val[0]):
            max_value = len(subtree_order)
            max_val = (max_order, max_used)
    max_val, max_val_list = max(max_val, key=lambda item: item[0]), list(filter(lambda item: item == max_val[1] or max_val[1] == order[order.index(max_val[1])], [i for i in order if i not in ancestors[1:]]))
    return [(order.index(i), order.index(max_val_list[index])) for index in range(len(max_val_list))]

if __name__ == "__main__":
    num_nodes = int(read())
    roots = [0]
    tree = defaultdict(lambda: [[]])
