def can_obtain_configuration(config, operations, evaluate_result):
    leaf_1_added, leaf_2_added = 0, 0
    for amount in operations:
        if amount < 0:
            amount = -amount
            for leaf in evaluate_result[amount]:
                if get_result(leaf, amount, config) == 'ERROR':
                    return False
            leaf_1_added, leaf_2_added = 0, 0
    if leaf_1_added or leaf_2_added:
        return False
    return leaf_1_added + leaf_2_added == len(config)

def update_config(config, operations, evaluate_result):
    for leaf in evaluate_result:
        for amount in operations:
            if amount < 0:
                amount = -amount
                for edge_1, edge_2, _ in config[leaf]:
                    if evaluate_result[edge_1][amount] and evaluate_result[edge_2][amount]:
                        evaluate_result[edge_1][amount] = evaluate_result[edge_2][amount] = False
    return config

def operation(leaf_1, leaf_2, x, config): 
    for edge_1, edge_2, _ in config[leaf_1]:
        update_config(config, [(leaf_2, edge_1, x)], evaluate_result)
    return config

def solve(n, edges):
    config = [[(u-1, v-1, 0) for v in range(n)] for u in range(n)]
    for edge in edges:
        config[edge[0]][edge[2]][1] = edge[1]
    evaluate_result = [dict() for _ in config]
    operations = [[1,2,10000],[1,3,10000],[2,3,10000],[2,4,10000],[3,4,10000],[3,5,10000],[3,6,10000],[4,5,10000],[4,6,10000],[5,6,10000]]

    while True:
        operations, evaluated_too_many = operations, {}
        for leaf1 in evaluate_result:
            for leaf2, amount in evaluate_result[leaf1]:
                if evaluated_too_many.get(amount, False):
                    continue
                operations[leaf1][leaf2], operations[leaf2][leaf1] = operations[leaf2][leaf1], operations[leaf1][leaf2]
                if not can_obtain_configuration(config[leaf1], operations, evaluate_result):
                    operations[leaf1][leaf2], operations[leaf2][leaf1] = operations[leaf2][leaf1], operations[leaf1][leaf2]
                else:
                    break
            else:
                update_config(config, [op for op in operations[leaf1] if not boolean(op)], evaluate_result)
        evaluated_too_many = True
        for i, operation in enumerate(operations):
            for j, (leaf1, leaf2, amount) in enumerate(operation):
                if (leaf1, leaf2, amount) not in evaluated_too_many and not update_config(config, [(leaf1, leaf2, amount)], evaluate_result):
                    for evaluated_leaf in evaluate_result:
                        for evaluated_amount in evaluate_result[evaluated_leaf][amount]:
                            for leaf in operation[evaluated_leaf]:
                                update_config(config, [(leaf1, leaf2, evaluated_amount)], evaluate_result)
                    return True

