import sys

sys.setrecursionlimit(100000)

class TreeNode:
    def __init__(self, character):
        self.character = character
        self.left = None
        self.right = None

def build_tree(colors):
    if len(colors) == 0:
        return None
    root_character = colors[0]
    root = TreeNode(root_character)
    queue = [root]
    colors.pop(0)
    while colors:
        current = queue.pop(0)
        for i in range(len(colors)):
            if colors[i] == 'B' and current.left is None:
                current.left = TreeNode('B')
                queue.append(current.left)
            if colors[i] == 'R' and current.right is None:
                current.right = TreeNode('R')
                queue.append(current.right)
            colors.pop(0)
    return root

def dfs(node, parent, parent_color):
    visited.add(node.character)
    if parent is not None and parent.character != node.character and node.character != 'B':
        return False
    if node.left and node.left.character == 'B':
        left = dfs(node.left, node, 'G')
    else:
        left = node.character == 'R'
    if node.right and node.right.character == 'B':
        right = dfs(node.right, node, 'R')
    else:
        right = node.character == 'G'
    return left and right

def is_valid(root, colors, node, visited, parent_color):
    if len(colors) == 0:
        return True
    node_without_parent = TreeNode(node.character)
    if parent_color is not None:
        node_without_parent.character = parent_color
    return dfs(root, node_without_parent, None)

T = int(input().strip())
for _ in range(T):
    N = int(input().strip())
    colors = []
    for i in range(N):
        colors.append(input().strip())
    root = None
    for index in range(N):
        queue = []
        for vertex in range(N):
            if vertex != index:
                queue.append((vertex, colors[index]))
        root = build_tree(queue)
    visited = set()
    parent_color = None
    if N == 2:
        parent_color = None
    elif N > 2:
        parent_color = colors[root.left.character]
    output = []
    for start in range(N):
        result = is_valid(root, colors, start, visited, parent_color)
        if result:
            output.append('Yes')
        else:
            output.append('No')
    print('\n'.join(output))

