import sys

def is_valid_coloring(tree, coloring):
    """
    Check if the given coloring of the tree forms a valid graph.

    :param tree: A list of tuples representing the edges between vertices.
    :param coloring: A string containing the color ('R', 'G', or 'B') for each vertex.
    :return: True if the coloring is valid, False otherwise.
    """
    # Flag to check if there's a path between any two blue nodes with a red or green vertex
    found_path = False

    def is_valid_reachable(blue_vertex, red_vertex, green_vertex):
        visited = set()
        queue = [(blue_vertex, red_vertex, green_vertex)]

        while queue:
            vertex, r, g = queue.pop(0)
            visited.add(vertex)

            if vertex in [red_vertex, green_vertex]:
                found_path = True  # Found a path with a red or green vertex between two blues

            for neighbor in tree[vertex]:
                if neighbor not in visited:
                    if neighbor == r or neighbor == g:
                        queue.append((neighbor, r, g))  # Update r and g while maintaining their paths
                    else:
                        return False  # No more valid paths can be found

        return found_path

    for vertex in range(1, len(coloring)):
        if coloring[vertex] == 'B':
            if is_valid_reachable(vertex, 'R', 'G'):
                return False
            if is_valid_reachable(vertex, 'G', 'R'):
                return False
    return True

def fast_input():
    lines = sys.stdin.read().splitlines()
    for line in lines:
        yield line

def parse_input(lines):
    num_tests = int(lines[0])
    for _ in range(num_tests):
        N = int(lines[1])
        coloring = lines[2]
        edges = [tuple(map(int, line.split())) for line in lines[3:]]
        yield edges, coloring

def main():
    test_cases = parse_input(fast_input())
    for case in test_cases:
        edges, coloring = case
        if is_valid_coloring(edges, coloring):
            print("Yes")
        else:
            print("No")

if __name__ == "__main__":
    main()
