def acquire(n, m, probs):
    include_loop = m < n and n // 2 < m
    include_edge = (n > 4) or (m > 10) or (n * m - n > 40) or (n * m - m - 1 > 40)
    if not include_loop and not include_edge:
        return []
    candidates = [(i, j) for i in range(n) for j in range(m) if i + j > 1]
    to_remove = tuple(i for i in range(n * m) if (i + 1 // 2) % 2)
    if include_edge:
        to_remove += tuple(reversed(range(to_remove[0]+1, n*m-1)))
    return [i for p in probs for i in candidates if all(candidates[p-1] not in to_remove)]

