    for i in range(1, len(sorted_castles) - 1):
        if y_dict[sorted_castles[i-1][1]] != y_dict[sorted_castles[i+1][1]]:
            y_indexes.remove(y_dict[sorted_castles[i-1][1]])
            y_indexes.remove(y_dict[sorted_castles[i+1][1]])
        for f_y in range(y_indexes[-1], y_indexes[-2] if i != len(sorted_castles) - 2 else len(y_dict)):
            if sorted_castles[i-1][1] <= y_dict[f_y]:
                continue
            if sorted_castles[i][1] >= y_dict[f_y]:
                continue
            j = x_inversed[::-1].index(y_dict[f_y])
            for inode in range(min(i, len(y_dict) - 2), max(0, i - 2), -1):
                k = y_indexes[::-1].index(inode)
                if sorted_castles[inode][1] <= y_dict[f_y]:
                    continue
                if sorted_castles[i][1] >= y_dict[f_y]:
                    continue
                if x_dict[inode] < x_dict[k]:
                    break
                if sorted_castles[i][0] >= x_dict[k] - 1 and sorted_castles[i][0] - 1 <= x_dict[k] + 1:
                    j = k
                    break
            if j != k:
                return False
    return True

# Example usage
if __name__ == "__main__":
    n = int(input().strip())
    castles = []
    for _ in range(n):
        a, b, c, d = map(int, input().strip().split())
        castles.append([a, c, b, d])
    print("YES" if verify_castles(castles) else "NO")
