from typing import List
import sys

def validate_input(N: int, colors: str, edges: List[List[int]]) -> bool:
    def create_edges(N: int, colors: str) -> List[List[int]]:
        edges = []
        for i in range(N):
            if colors[i] != 'B':
                edges.append([i, -1])
            else:
                for j in range(i + 1, N):
                    if colors[j] != 'B':
                        edges.append([i, j])
        return edges

    path_valid = True

    def is_path_valid(u: int, v: int) -> bool:
        green_count = 0
        red_count = 0
        while u != -1:
            if colors[u] == 'G':
                green_count += 1
            else:
                red_count += 1
            if green_count > 0 and red_count > 0:
                break
            u = -1
        while v != -1:
            if colors[v] == 'G':
                green_count += 1
            else:
                red_count += 1
            if green_count > 0 and red_count > 0:
                break
            v = -1

        return green_count > 0 and red_count > 0

    edges = create_edges(N, colors)
    for i in range(N - 1):
        u, v = edges[i]
        for j in range(i + 1, N):
            u_prime, v_prime = edges[j]
            if u == u_prime and not is_path_valid(u, v):
                return False
            if v == v_prime and not is_path_valid(v, u):
                return False

    return True

def read() -> List[List[int]]:
    N = int(input())
    edges: List[List[int]] = []
    for _ in range(N - 1):
        u, v = map(int, input().split())
        edges.append([u - 1, v - 1])
    return edges

if __name__ == "__main__":
    T = int(input())
    for _ in range(T):
        N = int(input())
        colors: str = input()
        edges = read()
        result = "Yes" if validate_input(N, colors, edges) else "No"
        print(result)
